sys_variable_value.value:
(function execute(inputs, outputs) {
    
    const api = new x_neyu_google_nyu.DirectoryMemberAPI();
    const response = api.deleteMember(inputs.groupKey, inputs.userKey);

    if (!response.error && response.status == 204) {
        outputs.error = false;
    } else {
        outputs.error = true;
        outputs.result = !gs.nil(response.errorMessage) ?
            response.errorMessage :
            JSON.stringify(JSON.parse(response.responseBody));
    }

})(inputs, outputs);

